#include "native.hpp"
using F=bitset<900>;using D=bitset<128>;
struct T{F a,b,d;bool ca,cb;uint32_t mask=0;};
struct B{vector<F> r,o;vector<uint64_t> c;uint64_t get(F x){F y=x;uint64_t v=0;for(int i=0;i<(int)r.size();i++)if(x[r[i]._Find_first()]){x^=r[i];v^=c[i];}if(x.none())return v;assert(r.size()<64);uint64_t z=1ull<<r.size();r.push_back(x);o.push_back(y);c.push_back(v^z);return z;}};
F unit(int i){F a;a.set(i);return a;}void trans(F&f,bool&c,Gate g){if(g.op==17)c^=f[g.a];else if(g.op==33){if(f[g.b])f.flip(g.a);}else if(g.op==34){bool a=f[g.a];f[g.a]=f[g.b];f[g.b]=a;}else abort();}
void dir(F&d,Gate g){if(g.op==33){if(d[g.a])d.flip(g.b);}else if(g.op==34){bool a=d[g.a];d[g.a]=d[g.b];d[g.b]=a;}else assert(g.op==17);}
// Physical compiler: factor the block as affine skeleton followed by its
// quadratic part. Move the latter past all 12 HMRs and contract the missing
// measured contribution against the original HMR outcome vector.
struct Plan{L l,h;vector<Gate>old,g;int paid;};
Gate gate(int op,U a=0,U b=0,U t=0,U bit=0,U cond=0){return {(unsigned char)op,a,b,t,bit,cond};}
void applyrow(vector<F>&v,Gate g){if(g.op==33)v[g.b]^=v[g.a];else if(g.op==34)swap(v[g.a],v[g.b]);else assert(g.op==17);}
vector<Gate> reduce_aff(vector<Gate> const&g){if(g.empty())return {};vector<F>rows(900);F c;for(int i=0;i<900;i++)rows[i].set(i);for(auto a:g){applyrow(rows,a);if(a.op==17)c.flip(a.a);else if(a.op==33){if(c[a.a])c.flip(a.b);}else{bool x=c[a.a];c[a.a]=c[a.b];c[a.b]=x;}}
 vector<Gate>best=g;for(int mode=0;mode<2;mode++){auto v=rows;vector<Gate>out;for(int k=0;k<900;k++){int j=mode?899-k:k,p=j;if(!v[j][j]){for(p=0;p<900;p++)if((mode?p<=j:p>=j)&&v[p][j])break;assert(p<900);swap(v[j],v[p]);out.push_back(gate(34,j,p));}for(int i=0;i<900;i++)if(i!=j&&v[i][j]){v[i]^=v[j];out.push_back(gate(33,j,i));}}for(int i=0;i<900;i++)assert(v[i]==unit(i));reverse(out.begin(),out.end());for(size_t i=c._Find_first();i<900;i=c._Find_next(i))out.push_back(gate(17,i));if(out.size()<best.size())best=move(out);}
 vector<F>check(900);F cc;for(int i=0;i<900;i++)check[i].set(i);for(auto a:best){applyrow(check,a);if(a.op==17)cc.flip(a.a);else if(a.op==33){if(cc[a.a])cc.flip(a.b);}else{bool x=cc[a.a];cc[a.a]=cc[a.b];cc[a.b]=x;}}assert(check==rows&&cc==c);return best;}
vector<Gate> squeeze(vector<Gate>const&g){vector<Gate>out,b;auto flush=[&](){auto z=reduce_aff(b);out.insert(out.end(),z.begin(),z.end());b.clear();};for(auto a:g){if(a.op==33||a.op==34||a.op==17)b.push_back(a);else{flush();out.push_back(a);}}flush();return out;}
struct Frame{vector<U>p;vector<Gate>g;};
Frame control_frame(vector<F>const&basis){auto rows=basis;vector<pair<int,int>> undo;vector<U>p;F used;int n=rows.size();for(int i=0;i<n;i++){int col=-1,j=-1;for(int k=0;k<900&&col<0;k++)if(!used[k])for(int z=i;z<n;z++)if(rows[z][k]){col=k;j=z;break;}assert(col>=0);p.push_back(col);used.set(col);if(j!=i){swap(rows[j],rows[i]);undo.push_back({j,i});undo.push_back({i,j});undo.push_back({j,i});}for(int z=0;z<n;z++)if(z!=i&&rows[z][col]){rows[z]^=rows[i];undo.push_back({i,z});}}
 vector<Gate>g;for(int i=0;i<n;i++){for(int j=0;j<n;j++)assert(rows[i][p[j]]==(i==j));for(size_t j=rows[i]._Find_first();j<900;j=rows[i]._Find_next(j))if(j!=p[i])g.push_back(gate(33,j,p[i]));}for(auto i=undo.rbegin();i!=undo.rend();i++)g.push_back(gate(33,p[i->first],p[i->second]));vector<F>q(900);for(int j=0;j<900;j++)q[j]=unit(j);for(auto a:g)applyrow(q,a);for(int i=0;i<n;i++)assert(q[p[i]]==basis[i]);return {p,g};}
vector<Gate> compile(vector<T>const&t,vector<Gate> const&skel,vector<U>const&mb,U scratch){B in,out;vector<tuple<uint64_t,uint64_t,uint64_t>>coord;for(auto a:t){auto x=in.get(a.a),y=in.get(a.b),z=out.get(a.d);coord.push_back({x,y,z});for(auto b:t)assert((a.a&b.d).count()%2==0&&(a.b&b.d).count()%2==0);}auto fr=control_frame(in.o);vector<F>d=out.o;for(auto a:fr.g)for(auto &x:d)dir(x,a);F used;for(auto p:fr.p)used.set(p);for(auto x:d)assert((x&used).none());vector<U>pout;for(int i=0;i<(int)d.size();i++){int p=-1;for(int j=0;j<900;j++)if(!used[j]&&d[i][j]){p=j;break;}assert(p>=0);pout.push_back(p);used.set(p);for(int j=0;j<900;j++)if(j!=p&&d[i][j]){auto g=gate(33,p,j);fr.g.push_back(g);for(auto&x:d)dir(x,g);}}for(int i=0;i<(int)d.size();i++)assert(d[i]==unit(pout[i]));
 // Prove the measured directions from the actual normalized survivor frame.
 const array<U,12> Lcol={647,3116,1915,1069,4088,1120,1966,2069,2053,1439,912,2957};
 const vector<pair<U,U>> net={{2,0},{10,5},{9,8},{7,4},{0,11},{1,2},{1,9},{11,2},{11,10},{8,11},{2,1},{7,2},{7,0},{7,3},{4,7},{6,5},{0,6},{9,0},{10,4},{10,9},{4,10},{9,4},{8,10},{11,8},{3,11},{5,3},{6,3},{7,6},{0,4},{8,7},{11,4},{3,1},{4,9},{5,4},{4,2},{2,6}};
 int first=t.size()==101?34:0,last=first+16,shift=t.size()==101?24:0;
 assert(t.size()==101||t.size()==67);assert(pout.size()>=shift+12&&mb.size()==12);
 assert(set<U>(mb.begin(),mb.end()).size()==12);
 for(U x=0;x<4096;x++) {
  U a=x,k=0;for(auto [i,j]:net)a^=((a>>i)&1)<<j;
  for(U i=0;i<12;i++)k|=(__builtin_parity(x&Lcol[i])<<i);
  assert(a==k);
 }
 for(int i=0;i<(int)t.size();i++){
  U d=(get<2>(coord[i])>>shift)&4095,h=0;
  for(U j=0;j<12;j++)if(d>>j&1)h^=Lcol[j];
  if(first<=i&&i<=last)assert(t[i].mask!=0&&t[i].mask==h);
  else assert(t[i].mask==0);
 }
 vector<Gate>res=squeeze(skel);res.insert(res.end(),fr.g.begin(),fr.g.end());auto translate=[&](bool inverse){
  if(!inverse)for(auto [j,k]:net)res.push_back(gate(194,0,0,0,mb[k],mb[j]));
  else for(auto it=net.rbegin();it!=net.rend();++it)res.push_back(gate(194,0,0,0,mb[it->second],mb[it->first]));
 };auto probe=[&](){for(U j=0;j<12;j++)res.push_back(gate(144,pout[shift+j],0,0,0,mb[j]));};
 for(int i=0;i<(int)t.size();i++){if(i==first){translate(false);probe();}auto [a,b,z]=coord[i];assert(a&&b&&a!=b);U p=__builtin_ctzll(a);uint64_t aa=a^(1ull<<p),bb=b;bool same=b>>p&1;if(same)bb^=a;assert(bb);U q=__builtin_ctzll(bb);assert(q!=p);bb^=1ull<<q;vector<Gate>pre;while(aa){int j=__builtin_ctzll(aa);aa&=aa-1;pre.push_back(gate(33,fr.p[j],fr.p[p]));}while(bb){int j=__builtin_ctzll(bb);bb&=bb-1;pre.push_back(gate(33,fr.p[j],fr.p[q]));}if(same)pre.push_back(gate(33,fr.p[p],fr.p[q]));if(t[i].ca)pre.push_back(gate(17,fr.p[p]));if(t[i].cb)pre.push_back(gate(17,fr.p[q]));res.insert(res.end(),pre.begin(),pre.end());if(z){U k=__builtin_ctzll(z);vector<Gate>fan;for(uint64_t w=z^(1ull<<k);w;w&=w-1)fan.push_back(gate(33,pout[k],pout[__builtin_ctzll(w)]));res.insert(res.end(),fan.begin(),fan.end());res.push_back(gate(49,fr.p[p],fr.p[q],pout[k]));res.insert(res.end(),fan.rbegin(),fan.rend());}res.insert(res.end(),pre.rbegin(),pre.rend());if(i==last){probe();translate(true);}}res.insert(res.end(),fr.g.rbegin(),fr.g.rend());return res;}
// arbitrary dirty 900-bit entry states and independent measurement outcomes;
// identical original HMR sequence ensures all later measurement draws agree.
struct Eval{vector<uint64_t>q;unordered_map<U,uint64_t>b;uint64_t ph=0;int m=0;};
Eval eval(vector<Gate>const&g,Eval s,array<uint64_t,12>const&coins){for(auto a:g){switch(a.op){case 17:s.q[a.a]^=~0ull;break;case 33:s.q[a.b]^=s.q[a.a];break;case 34:swap(s.q[a.a],s.q[a.b]);break;case 49:s.q[a.t]^=s.q[a.a]&s.q[a.b];break;case 80:{auto m=coins.at(s.m++);s.ph^=m&s.q[a.a];s.b[a.bit]=m;s.q[a.a]=0;break;}case 64:s.b[a.bit]=0;break;case 194:s.b[a.bit]^=s.b[a.cond];break;case 144:s.ph^=s.q[a.a]&s.b[a.cond];break;case 160:s.ph^=s.q[a.a]&s.q[a.b]&s.b[a.cond];break;default:abort();}}return s;}
void localcheck(Plan const&p,U scratch){mt19937_64 rng(p.l);for(int i=0;i<128;i++){Eval s;s.q.resize(900);for(auto&x:s.q)x=rng();array<uint64_t,12>m;for(auto&x:m)x=rng();auto a=eval(p.old,s,m),b=eval(p.g,s,m);assert(a.q==b.q&&a.ph==b.ph&&a.m==b.m&&a.m==12);assert(b.b[scratch]==0);b.b.erase(scratch);assert(a.b==b.b);}}
int main(int ac,char**av){Reader r(av[1]);ifstream f(av[2]);map<L,L>iv;int n,dim,obs,axes,s,dep;L l,h;while(f>>l>>h>>n>>dim>>obs>>axes>>s>>dep)iv[l]=h;ofstream o(av[3]),eb("new/folded_entry_basis.tsv");vector<Plan>plans;for(L i=0;i<r.counts[0];i++){Gate g=r.read(i);auto it=iv.find(i);if(it==iv.end())continue;L l=i,h=it->second;vector<F>a(900);vector<char>c(900);vector<D>d(900);for(int j=0;j<900;j++)a[j].set(j);vector<T>t;vector<Gate>aff,old,skel;vector<U>mb;for(;i<=h;i++){if(i!=l)g=r.read(i);old.push_back(g);if(g.op!=49)skel.push_back(g);if(g.op==49){assert(d[g.a].none()&&d[g.b].none());t.push_back({a[g.a],a[g.b],{},bool(c[g.a]),bool(c[g.b])});d[g.t].flip(t.size()-1);}else{aff.push_back(g);if(g.op==17)c[g.a]^=1;else if(g.op==33){a[g.b]^=a[g.a];d[g.b]^=d[g.a];c[g.b]^=c[g.a];}else if(g.op==34){swap(a[g.a],a[g.b]);swap(d[g.a],d[g.b]);swap(c[g.a],c[g.b]);}else abort();}}i=h;for(int j=0;j<900;j++)for(size_t k=d[j]._Find_first();k<128;k=d[j]._Find_next(k))t[k].d.set(j);B entry;for(auto x:t){entry.get(x.a);entry.get(x.b);}eb<<l<<" "<<entry.o.size()<<"\n";for(auto v:entry.o)eb<<v.to_string()<<"\n";for(auto &x:t)for(auto g:aff){trans(x.a,x.ca,g);trans(x.b,x.cb,g);}int bad=0,m=0;vector<Gate> suf;while(i+1<r.counts[0]&&m<12){g=r.read(++i);suf.push_back(g);old.push_back(g);skel.push_back(g);if(g.op==80){mb.push_back(g.bit);for(auto &x:t){if(x.a[g.a]||x.b[g.a])bad++;if(x.d[g.a])x.mask^=1u<<m;x.d.reset(g.a);}m++;}else if(g.op==17||g.op==33||g.op==34){for(auto &x:t){trans(x.a,x.ca,g);trans(x.b,x.cb,g);dir(x.d,g);}}else{bad+=10000;break;}}assert(!bad&&m==12);auto compiled=compile(t,skel,mb,r.B);Plan p{l,i,old,compiled,(int)t.size()};localcheck(p,r.B);cout<<"PHYSICAL "<<l<<" old "<<old.size()<<" new "<<compiled.size()<<" paid "<<t.size()<<" local 8192 PASS"<<endl;plans.push_back(move(p));B in,out;int zeros=0;set<uint64_t> distinct;vector<tuple<uint64_t,uint64_t,uint64_t>>rows;for(auto x:t){uint64_t aa=in.get(x.a),bb=in.get(x.b),dd=out.get(x.d);distinct.insert(dd);zeros+=!dd;rows.push_back({aa,bb,dd});}cout<<l<<' '<<h<<' '<<i<<' '<<t.size()<<' '<<in.r.size()<<' '<<out.r.size()<<' '<<m<<' '<<bad<<' '<<zeros<<' '<<distinct.size()<<endl;o<<l<<' '<<h<<' '<<i<<' '<<t.size()<<' '<<in.r.size()<<' '<<out.r.size()<<' '<<bad<<'\n';for(auto [a,b,c]:rows)o<<a<<' '<<b<<' '<<c<<'\n';}assert(plans.size()==17);r.reset();Writer w(r,r.B);size_t k=0;for(L i=0;i<r.counts[0];i++){auto g=r.read(i);if(k<plans.size()&&i==plans[k].l){for(auto x:plans[k].g)w.put(x);for(;i<plans[k].h;i++)r.read(i+1);k++;}else w.put(g);}assert(k==plans.size()&&w.a[2].size()==r.counts[1]);w.write(av[4]);cout<<"FULL ops "<<r.counts[0]<<" -> "<<w.ops.size()<<" paid "<<r.counts[1]<<" Q "<<r.Q<<endl;}
